WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM payments), sessions_payments AS (SELECT id, order_id, amount, paid_at, status, SUM(new_group_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT s.id, s.order_id, s.amount, s.paid_at, s.status, s.burst_id, CASE WHEN status RLIKE '^(FAILED|SUCCESS)$' THEN 'PRIORITY' WHEN status RLIKE '^(REFUNDED)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS status_zone, (SELECT MIN(s2.cost) FROM shipments s2 WHERE s2.order_id = s.order_id) AS min_shipment_cost FROM sessions_payments s;
